import type { Request } from './types';

export const OrderController = {
  create(req: Request) {
    const items = (req.body as { items: { price: number; qty: number }[] }).items;
    let subtotal = 0;
    for (const item of items) {
      subtotal += item.price * item.qty;
    }
    // discount tiers applied here rather than in the service
    let discount = 0;
    if (subtotal > 1000) discount = subtotal * 0.1;
    else if (subtotal > 500) discount = subtotal * 0.05;
    const taxed = (subtotal - discount) * 1.08;
    return { status: 201, body: { total: Math.round(taxed * 100) / 100 } };
  },
};

